<?php
require_once __DIR__.'/../../../utils/worker_documents.php';
$units=$pdo->query('SELECT * FROM business_units ORDER BY is_active DESC,name')->fetchAll(PDO::FETCH_ASSOC);
$workers=$pdo->query('SELECT wp.id,wp.user_id,wp.display_name,wp.relationship_type,COUNT(wd.id) document_count FROM worker_profiles wp LEFT JOIN worker_documents wd ON wd.worker_profile_id=wp.id WHERE wp.status="active" GROUP BY wp.id ORDER BY wp.display_name')->fetchAll(PDO::FETCH_ASSOC);
$workerProfiles=$pdo->query('SELECT wp.id,wp.user_id,wp.display_name,wp.relationship_type,wp.relationship_review_required,wp.relationship_review_reason,wp.time_review_policy,wp.compensation_policy,wp.status,wp.currency,COALESCE(NULLIF(u.username,""),u.email) account_name FROM worker_profiles wp LEFT JOIN users u ON u.id=wp.user_id ORDER BY wp.relationship_review_required DESC,wp.status="active" DESC,wp.display_name')->fetchAll(PDO::FETCH_ASSOC);
$clients=$pdo->query('SELECT id,name FROM clients WHERE archived=0 AND deleted_at IS NULL ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);
$accounts=$pdo->query('SELECT u.id,COALESCE(NULLIF(u.username,""),u.email) name FROM users u LEFT JOIN worker_profiles wp ON wp.user_id=u.id WHERE u.deleted_at IS NULL AND u.is_disabled=0 AND wp.id IS NULL ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);
$scopes=$pdo->query('SELECT s.*,wp.display_name FROM worker_capability_scopes s JOIN worker_profiles wp ON wp.id=s.worker_profile_id WHERE s.allowed=1 ORDER BY wp.display_name,s.capability')->fetchAll(PDO::FETCH_ASSOC);
$selectedWorkerId=max(0,(int)($_GET['worker_profile_id']??0));$selectedWorker=null;$workerDocuments=[];
$canManageWorkerDocuments=user_can($pdo,(int)($_SESSION['user']['id']??0),'users.manage',0);
if($selectedWorkerId>0&&$canManageWorkerDocuments){$selectedStmt=$pdo->prepare('SELECT id,user_id,display_name,relationship_type FROM worker_profiles WHERE id=?');$selectedStmt->execute([$selectedWorkerId]);$selectedWorker=$selectedStmt->fetch(PDO::FETCH_ASSOC);if($selectedWorker){$documentStmt=$pdo->prepare('SELECT wd.*,COALESCE(NULLIF(u.username,""),u.email,"System") uploaded_by_name FROM worker_documents wd LEFT JOIN users u ON u.id=wd.uploaded_by WHERE wd.worker_profile_id=? ORDER BY wd.status="current" DESC,wd.created_at DESC');$documentStmt->execute([$selectedWorkerId]);$workerDocuments=$documentStmt->fetchAll(PDO::FETCH_ASSOC);}}
$documentCategories=worker_document_category_labels();
$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?>
<?php if(!empty($_GET['document_msg'])):?><div class="alert alert-success"><?=$h($_GET['document_msg'])?></div><?php endif;?>
<?php if(!empty($_GET['document_error'])):?><div class="alert alert-danger"><?=$h($_GET['document_error'])?></div><?php endif;?>
<form method="post" action="/?page=settings/workforce-catalog-handler" class="settings-card"><input type="hidden" name="csrf" value="<?=$h(csrf_token())?>"><input type="hidden" name="action" value="save-worker-profile"><input type="hidden" name="return_tab" value="business-units"><h3>Add worker profile</h3><p>A worker may exist without a PA login. Relationship, compensation, and account access are separate choices. New profiles require manager review by default.</p><div class="settings-form-grid"><label class="field"><span class="label">Display name</span><input class="input" name="display_name" required></label><label class="field"><span class="label">Relationship</span><input class="input" name="relationship_type" value="employee" list="worker-relationships" required><datalist id="worker-relationships"><option value="owner"><option value="employee"><option value="contractor"></datalist></label><label class="field"><span class="label">Compensation</span><select class="input" name="compensation_policy"><option value="needs_setup">Needs setup</option><option value="rules">Pay using rules</option><option value="nonpayable">Nonpayable</option></select></label><label class="field"><span class="label">Optional PA account</span><select class="input" name="user_id"><option value="">No login</option><?php foreach($accounts as $a):?><option value="<?=(int)$a['id']?>"><?=$h($a['name'])?></option><?php endforeach;?></select></label><label class="field"><span class="label">Currency</span><input class="input" name="currency" value="USD" maxlength="3"></label></div><button class="btn btn-primary">Add worker</button></form>
<?php if($workerProfiles):?><div class="settings-card"><h3>Worker profiles</h3><p>Relationship, time review, compensation, and account access are independent choices.</p><div class="pa-table-wrap"><table class="pa-table"><thead><tr><th>Worker</th><th>Relationship</th><th>Time review</th><th>Compensation</th><th>Status</th><th>Currency</th><th class="text-right">Action</th></tr></thead><tbody><?php foreach($workerProfiles as $profile):$profileForm='worker-profile-'.(int)$profile['id'];?><tr><td><input form="<?=$profileForm?>" class="input input--small" name="display_name" value="<?=$h($profile['display_name'])?>" required><?php if($profile['account_name']):?><small><?=$h($profile['account_name'])?></small><?php endif;?><?php if(!empty($profile['relationship_review_required'])):?><small style="color:#9a3412"><strong>Relationship verification required:</strong> own time requires another reviewer until confirmed.</small><?php endif;?></td><td><input form="<?=$profileForm?>" class="input input--small" name="relationship_type" value="<?=$h($profile['relationship_type'])?>" list="worker-relationships" required></td><td><span class="input input--small" aria-label="Time review policy"><?=$h(str_replace('_',' ',ucfirst($profile['time_review_policy'])))?></span></td><td><select form="<?=$profileForm?>" class="input input--small" name="compensation_policy"><?php foreach(['needs_setup'=>'Needs setup','rules'=>'Pay using rules','nonpayable'=>'Nonpayable','owner_no_pay'=>'Legacy owner no pay'] as $value=>$label):?><option value="<?=$value?>" <?=$profile['compensation_policy']===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></td><td><select form="<?=$profileForm?>" class="input input--small" name="status"><?php foreach(['active'=>'Active','inactive'=>'Inactive','terminated'=>'Terminated'] as $value=>$label):?><option value="<?=$value?>" <?=$profile['status']===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></td><td><input form="<?=$profileForm?>" class="input input--small" name="currency" maxlength="3" value="<?=$h($profile['currency'])?>" required></td><td class="text-right"><form id="<?=$profileForm?>" method="post" action="/?page=settings/workforce-catalog-handler" class="inline-form"><input type="hidden" name="csrf" value="<?=$h(csrf_token())?>"><input type="hidden" name="action" value="save-worker-profile"><input type="hidden" name="return_tab" value="business-units"><input type="hidden" name="id" value="<?=(int)$profile['id']?>"><input type="hidden" name="user_id" value="<?=(int)($profile['user_id']??0)?>"><button class="btn btn-sm"><?=!empty($profile['relationship_review_required'])?'Confirm relationship':'Save'?></button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?>
<?php if($units):?><form method="post" action="/?page=settings/workforce-catalog-handler" class="settings-card"><input type="hidden" name="csrf" value="<?=$h(csrf_token())?>"><input type="hidden" name="action" value="assign-worker-unit"><input type="hidden" name="return_tab" value="business-units"><h3>Assign worker</h3><div class="settings-form-grid"><label class="field"><span class="label">Worker</span><select class="input" name="worker_profile_id"><?php foreach($workers as $w):?><option value="<?=(int)$w['id']?>"><?=$h($w['display_name'].' · '.$w['relationship_type'])?></option><?php endforeach;?></select></label><label class="field"><span class="label">Business unit</span><select class="input" name="business_unit_id"><?php foreach($units as $u):?><option value="<?=(int)$u['id']?>"><?=$h($u['name'])?></option><?php endforeach;?></select></label><label class="check-row"><input type="checkbox" name="is_lead" value="1"> Business-unit lead</label></div><button class="btn btn-primary">Assign worker</button></form>
<form method="post" action="/?page=settings/workforce-catalog-handler" class="settings-card"><input type="hidden" name="csrf" value="<?=$h(csrf_token())?>"><input type="hidden" name="action" value="assign-client-unit"><input type="hidden" name="return_tab" value="business-units"><h3>Assign client</h3><p>A client stays in the shared directory but may belong to several business units.</p><div class="settings-form-grid"><label class="field"><span class="label">Client</span><select class="input" name="client_id"><?php foreach($clients as $c):?><option value="<?=(int)$c['id']?>"><?=$h($c['name'])?></option><?php endforeach;?></select></label><label class="field"><span class="label">Business unit</span><select class="input" name="business_unit_id"><?php foreach($units as $u):?><option value="<?=(int)$u['id']?>"><?=$h($u['name'])?></option><?php endforeach;?></select></label></div><button class="btn btn-primary">Assign client</button></form><?php endif;?>
<form method="post" action="/?page=settings/workforce-catalog-handler" class="settings-card"><input type="hidden" name="csrf" value="<?=$h(csrf_token())?>"><input type="hidden" name="action" value="save-worker-scope"><input type="hidden" name="return_tab" value="business-units"><h3>Worker capability and scope</h3><p>Worker relationship never grants access. Give each capability the smallest suitable scope. Review and management capabilities control both the desktop pages and their backend actions.</p><div class="settings-form-grid"><label class="field"><span class="label">Worker</span><select class="input" name="worker_profile_id"><?php foreach($workers as $w):?><option value="<?=(int)$w['id']?>"><?=$h($w['display_name'])?></option><?php endforeach;?></select></label><label class="field"><span class="label">Capability</span><select class="input" name="capability"><?php foreach(['clients.search'=>'Find clients','jobs.view'=>'View Jobs','documents.create'=>'Create documents','documents.view'=>'View documents','timekeeping.self'=>'Track own time','timekeeping.manage'=>'Manage scoped team time','approvals.review'=>'Review scoped submitted time','mileage.self'=>'Track mileage','workforce.assignments.manage'=>'Manage work assignments','workforce.pay_periods.manage'=>'Manage pay periods','workforce.statements.self'=>'View own statements','workforce.statements.manage'=>'Manage worker statements'] as $v=>$l):?><option value="<?=$h($v)?>"><?=$h($l)?></option><?php endforeach;?></select></label><label class="field"><span class="label">Scope</span><select class="input" name="access_scope"><option value="own">Their own records</option><option value="assigned">Assigned records</option><option value="business_unit">Their business units</option><option value="all">All business data</option></select></label></div><button class="btn btn-primary">Save access</button></form>
<?php if($scopes):?><div class="pa-table-wrap"><table class="pa-table"><thead><tr><th>Worker</th><th>Capability</th><th>Scope</th></tr></thead><tbody><?php foreach($scopes as $s):?><tr><td><?=$h($s['display_name'])?></td><td><?=$h($s['capability'])?></td><td><?=$h(str_replace('_',' ',ucfirst($s['access_scope'])))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<div class="settings-card"><h3>Worker documents and agreements</h3><p>Keep equipment-use agreements, waivers, certifications, and other signed records with each worker, including workers who do not have a PA login.</p><?php if(!$canManageWorkerDocuments):?><div class="alert alert-info">Worker agreements are read-only here. User-management permission is required to attach, archive, or restore signed files.</div><?php endif;?><div class="pa-table-wrap"><table class="pa-table"><thead><tr><th>Worker</th><th>Relationship</th><th>Documents</th><?php if($canManageWorkerDocuments):?><th class="text-right">Action</th><?php endif;?></tr></thead><tbody><?php foreach($workers as $w):?><tr><td><?=$h($w['display_name'])?></td><td><?=$h(ucfirst($w['relationship_type']))?></td><td><?=(int)$w['document_count']?></td><?php if($canManageWorkerDocuments):?><td class="text-right"><a class="btn btn-sm" href="/?page=settings&amp;tab=business-units&amp;worker_profile_id=<?=(int)$w['id']?>#worker-documents">Manage documents</a></td><?php endif;?></tr><?php endforeach;?><?php if(!$workers):?><tr><td colspan="<?=$canManageWorkerDocuments?4:3?>">Add a worker profile before attaching agreements.</td></tr><?php endif;?></tbody></table></div></div>
<?php if($selectedWorker):?><div class="settings-card" id="worker-documents"><h3><?=$h($selectedWorker['display_name'])?> — documents</h3><?php if($workerDocuments):?><div class="pa-table-wrap"><table class="pa-table"><thead><tr><th>Document</th><th>Signed / expires</th><th>Status</th><th class="text-right">Action</th></tr></thead><tbody><?php foreach($workerDocuments as $document):$archived=$document['status']==='archived';?><tr><td><a href="/?page=worker-document-download&amp;id=<?=(int)$document['id']?>" target="_blank" rel="noopener"><strong><?=$h($document['title'])?></strong></a><small><?=$h($documentCategories[$document['category']]??$document['category'])?> · uploaded <?=$h($document['created_at'])?></small></td><td><?=$h($document['signed_on']?:'Not recorded')?> / <?=$h($document['expires_on']?:'No expiry')?></td><td><?=$archived?'Archived':'Current'?></td><td class="text-right"><form method="post" action="/?page=worker-documents" class="inline-form"><input type="hidden" name="csrf" value="<?=$h(csrf_token())?>"><input type="hidden" name="return_tab" value="business-units"><input type="hidden" name="worker_profile_id" value="<?=(int)$selectedWorker['id']?>"><input type="hidden" name="document_id" value="<?=(int)$document['id']?>"><input type="hidden" name="action" value="<?=$archived?'restore':'archive'?>"><button class="btn btn-sm"><?=$archived?'Restore':'Archive'?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No agreements are attached to this worker yet.</p><?php endif;?><form method="post" action="/?page=worker-documents" enctype="multipart/form-data" class="settings-primary-form"><input type="hidden" name="csrf" value="<?=$h(csrf_token())?>"><input type="hidden" name="return_tab" value="business-units"><input type="hidden" name="worker_profile_id" value="<?=(int)$selectedWorker['id']?>"><input type="hidden" name="action" value="upload"><div class="settings-form-grid"><label class="field"><span class="label">Document type</span><select class="input" name="category"><?php foreach($documentCategories as $key=>$label):?><option value="<?=$h($key)?>"><?=$h($label)?></option><?php endforeach;?></select></label><label class="field"><span class="label">Title</span><input class="input" name="title" maxlength="255" required placeholder="Drone equipment use agreement"></label><label class="field"><span class="label">Signed date</span><input class="input" type="date" name="signed_on"></label><label class="field"><span class="label">Expiration date</span><input class="input" type="date" name="expires_on"></label><label class="field"><span class="label">Notes</span><input class="input" name="notes" maxlength="5000"></label><label class="field"><span class="label">Signed file</span><input class="input" type="file" name="worker_document" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx" required></label><?php if(!empty($selectedWorker['user_id'])):?><label class="check-row"><input type="checkbox" name="worker_visible" value="1"> Let this worker view the file</label><?php endif;?></div><div class="settings-save-actions"><button class="btn btn-primary">Attach document</button></div></form><p class="muted">PDF, Word, JPG, or PNG; maximum 15 MB. Archiving keeps the original file and audit history.</p></div><?php endif;?>
